"""Scenario families for similarity/symmetry, area THEOREMS/CONSTRUCTIONS, mensuration."""
from ssc_math_remaining_models import *
from ssc_math_remaining_figures import plane,tri,rect,pair,midpoint,para,median,circles,solid

def scenarios14(n):
 k=S.Integer(n+2);r=k+1;rows=[]
 def add(*args,**kw):rows.append(row(*args,**kw))
 add('similar-sides',rf'$\triangle ABC\sim\triangle PQR$; A↔P,B↔Q,C↔R। AB=3, BC=4, CA=5 সেমি এবং PQ={3*k} সেমি।',Q('বড়/ছোট সদৃশতার গুণক কত?',k,rf'$PQ/AB={3*k}/3={k}$।'),Q('QR কত সেমি?',4*k,rf'$QR/BC=PQ/AB={k}$; $QR=4\times{k}={4*k}$ সেমি।'),Q('বড় ত্রিভুজের পরিসীমা কত সেমি এবং কেন পরিসীমার অনুপাতও k?',12*k,rf'$PR={5*k}$; পরিসীমা ${3*k}+{4*k}+{5*k}={12*k}$। প্রতিটি অনুরূপ বাহু {k} গুণ, তাই যোগফলও {k} গুণ।'),pair(float(k)),k=k)
 add('parallel-intercept',rf'ত্রিভুজ ABC-তে D∈AB, E∈AC এবং DE∥BC। AD/AB=1/{k}, BC={3*k} সেমি ও AC={4*k} সেমি।',Q('AD/DB-এর ভগ্নাংশমান কত?',1/(k-1),rf'$AD=AB/{k}$; $DB=({k-1}/{k})AB$; অনুপাত ${T(1/(k-1))}$।'),Q('DE কত সেমি?',3,rf'∠ADE=∠ABC ও ∠AED=∠ACB (সমান্তরাল রেখায় অনুরূপ কোণ), তাই AA-এ ADE∼ABC। $DE/BC=AD/AB=1/{k}$; DE=3 সেমি।'),Q('ত্রিভুজ ADE-এর ক্ষেত্রফল ত্রিভুজ ABC-এর কত অংশ?',1/(k*k),rf'সদৃশ ত্রিভুজের ক্ষেত্রফলের অনুপাত অনুরূপ বাহুর অনুপাতের বর্গ। তাই $(1/{k})^2=1/{k*k}$।'),plane(dict(A=(0,4),B=(0,0),C=(3,0),D=(0,4-4/float(k)),E=(3/float(k),4-4/float(k))),['AB','BC','CA','DE']),k=k)
 add('similar-areas',rf'দুটি সদৃশ ত্রিভুজের অনুরূপ বাহুর অনুপাত 2:{k+2} এবং ছোটটির ক্ষেত্রফল 12 বর্গসেমি।',Q('বড়/ছোট রৈখিক গুণক কত?',(k+2)/2,rf'গুণক $({k+2})/2={T((k+2)/2)}$।'),Q('বড়টির ক্ষেত্রফল কত বর্গসেমি?',3*(k+2)**2,rf'$A_2/A_1=[({k+2})/2]^2$; $A_2=12\times({k+2})^2/4={3*(k+2)**2}$।'),Q('বড়টির ক্ষেত্রফল থেকে ছোটটির ক্ষেত্রফল বাদ দিলে কত?',3*(k+2)**2-12,rf'পার্থক্য ${3*(k+2)**2}-12={3*(k+2)**2-12}$ বর্গসেমি। ক্ষেত্রফল রৈখিক অনুপাতে বাড়ে না।'),pair(float((k+2)/2)),k=k)
 add('reflection',rf'কার্তেসীয় সমতলে A=({k},2), B=({k+3},2), C=({k},6)। y-অক্ষের সাপেক্ষে প্রতিফলিত বিন্দুগুলো P,Q,R।',Q('P-এর x-স্থানাঙ্ক কত?',-k,rf'y-অক্ষে প্রতিফলনের নিয়ম $(x,y)\mapsto(-x,y)$; P=({-k},2)।'),Q('PQ-এর দৈর্ঘ্য কত একক?',3,r'$AB=3$; প্রতিফলন দূরত্ব সংরক্ষণ করে, তাই PQ=3।'),Q('প্রতিফলিত ত্রিভুজের ক্ষেত্রফল কত বর্গএকক?',6,r'AB=3, AC=4, AB⊥AC। মূল ক্ষেত্রফল $\frac12(3)(4)=6$। প্রতিফলন দৈর্ঘ্য ও লম্বত্ব সংরক্ষণ করে; প্রতিচ্ছবির ক্ষেত্রফলও 6, অভিমুখ বিপরীত।'),plane(dict(A=(k,2),B=(k+3,2),C=(k,6),P=(-k,2),Q=(-k-3,2),R=(-k,6),O=(0,0),Y=(0,7)),['AB','BC','CA','PQ','QR','RP','OY']),k=k)
 add('rotation',rf'O=(0,0) কেন্দ্র করে A=({k},1) বিন্দুকে ঘড়ির কাঁটার বিপরীতে 90° ঘোরালে P হয়।',Q('P-এর x-স্থানাঙ্ক কত?',-1,r'নিয়ম $(x,y)\mapsto(-y,x)$; x-স্থানাঙ্ক −1।'),Q('P-এর y-স্থানাঙ্ক কত?',k,rf'P=(-1,{k}); y-স্থানাঙ্ক {k}।'),Q('OA² ও OP²-এর সাধারণ মান কত?',k*k+1,rf'$OA^2={k}^2+1^2={k*k+1}$ এবং $OP^2=(-1)^2+{k}^2={k*k+1}$। আবর্তনে কেন্দ্র থেকে দূরত্ব অপরিবর্তিত।'),plane(dict(O=(0,0),A=(k,1),P=(-1,k)),['OA','OP']),k=k)
 N=int(k+3)
 points={chr(65+i):(S.cos(2*S.pi*i/N).evalf(),S.sin(2*S.pi*i/N).evalf()) for i in range(N)}
 edges=[chr(65+i)+chr(65+(i+1)%N) for i in range(N)]
 add('regular-symmetry',rf'একটি সুষম {N}-ভুজের প্রতিফলন ও আবর্তন প্রতিসমতা বিবেচনা কর।',Q('এর প্রতিসাম্য অক্ষের সংখ্যা কত?',N,rf'সুষম n-ভুজে nটি প্রতিসাম্য অক্ষ; এখানে {N}টি।'),Q('ক্ষুদ্রতম ধনাত্মক আবর্তন কোণ কত ডিগ্রি?',R(360,N),rf'$360^\circ/{N}={T(R(360,N))}^\circ$।'),Q('360°-এর কম ধনাত্মক কতটি কোণে নিজের সঙ্গে মিলে যাবে?',N-1,rf'θ,2θ,…,({N-1})θ; মোট {N-1}টি। পূর্ণ 360°-সহ আবর্তন-প্রতিসাম্যের ক্রম {N}।'),plane(points,edges),k=k,N=N)
 add('angle-bisector',rf'ত্রিভুজ ABC-তে AD হলো A-কোণের অন্তঃসমদ্বিখণ্ডক; D∈BC। AB={2*k}, AC={3*k}, BC={5*k} সেমি।',Q('BD/DC-এর ভগ্নাংশমান কত?',R(2,3),rf'অন্তঃকোণ সমদ্বিখণ্ডক উপপাদ্যে $BD/DC=AB/AC={2*k}/{3*k}=2/3$।'),Q('BD কত সেমি?',2*k,rf'$BD=\frac25BC=\frac25({5*k})={2*k}$ সেমি।'),Q('ADC-এর ক্ষেত্রফল থেকে ABD-এর ক্ষেত্রফল বাদ দিলে তা ABC-এর কত অংশ?',R(1,5),r'একই A থেকে BC-এর উপর লম্ব উচ্চতা। তাই ক্ষেত্রফল অনুপাত BD:DC=2:3। পার্থক্য/মোট=(3−2)/(3+2)=1/5।'),plane(dict(A=(0,6),B=(-4,0),C=(6,0),D=(0,0)),['AB','BC','CA','AD']),k=k)
 # Schematic above for angle-bisector must satisfy length ratio 2:3. Use exact 2:3 sides with 4k base, not degenerate 2k+3k=5k.
 rows[-1]['stem']=rf'ত্রিভুজ ABC-তে AD হলো A-কোণের অন্তঃসমদ্বিখণ্ডক; D∈BC। AB={2*k}, AC={3*k}, BC={4*k} সেমি।'
 rows[-1]['parts'][1]=Q('BD কত সেমি?',R(8,5)*k,rf'$BD=\frac25BC=\frac25({4*k})={T(R(8,5)*k)}$ সেমি।')
 # Coordinates from the three side lengths: A projection onto base has x=11k/8; height sqrt(135)k/8.
 rows[-1]['figure']=plane(dict(A=(float(R(11,8)*k),float(S.sqrt(135)*k/8)),B=(0,0),C=(4*k,0),D=(float(R(8,5)*k),0)),['AB','BC','CA','AD'])
 add('rectangle-similarity',rf'একটি আয়তক্ষেত্রের দৈর্ঘ্য 6 ও প্রস্থ 4 সেমি। সদৃশ বড় আয়তক্ষেত্রের দৈর্ঘ্য {6*k} সেমি।',Q('দৈর্ঘ্যের গুণক কত?',k,rf'${6*k}/6={k}$।'),Q('বড় আয়তক্ষেত্রের প্রস্থ কত সেমি?',4*k,rf'সদৃশতার জন্য উভয় রৈখিক মাপ একই গুণকে বাড়ে; প্রস্থ $4\times{k}={4*k}$।'),Q('বড় আয়তক্ষেত্রের ক্ষেত্রফল কত বর্গসেমি?',24*k*k,rf'${6*k}\times{4*k}={24*k*k}$; ক্ষেত্রফলের গুণক ${k*k}$। শুধু সব কোণ সমকোণ হলেই দুই আয়তক্ষেত্র সদৃশ হয় না; বাহুর অনুপাতও সমান চাই।'),rect(6*k,4*k),k=k)
 add('shadow-similarity',rf'একই সময়ে সমতল ভূমিতে 2 মিটার লম্ব খুঁটির ছায়া 3 মিটার এবং একটি উল্লম্ব গাছের ছায়া {3*k} মিটার। সূর্যরশ্মি পরস্পর সমান্তরাল।',Q('ছায়ার বড়/ছোট অনুপাত কত?',k,rf'${3*k}/3={k}$।'),Q('গাছের উচ্চতা কত মিটার?',2*k,rf'সমকোণ ও সমান্তরাল সূর্যরশ্মির অনুরূপ কোণে ত্রিভুজ দুটি সদৃশ। $H/2={3*k}/3={k}$; H={2*k} মিটার।'),Q('উচ্চতা-ছায়া ত্রিভুজদ্বয়ের ক্ষেত্রফলের বড়/ছোট অনুপাত কত?',k*k,rf'সদৃশতার রৈখিক গুণক {k}; ক্ষেত্রফলের অনুপাত ${k}^2={k*k}$।'),plane(dict(A=(0,2),B=(0,0),C=(3,0),P=(5,2*k),Q=(5,0),R=(5+3*k,0)),['AB','BC','CA','PQ','QR','RP']),k=k)
 add('similar-construction',rf'AB=3, BC=4, CA=5 সেমি ত্রিভুজ ABC-এর {k} গুণ অনুরূপ বাহুবিশিষ্ট ত্রিভুজ নির্মাণ করতে হবে।',Q('নতুন AB-অনুরূপ বাহুর দৈর্ঘ্য কত সেমি?',3*k,rf'$3\times{k}={3*k}$।'),Q('নতুন BC-অনুরূপ বাহুর দৈর্ঘ্য কত সেমি?',4*k,rf'$4\times{k}={4*k}$।'),Q('নতুন ত্রিভুজের ক্ষেত্রফল কত বর্গসেমি? নির্মাণ ও যুক্তি লেখ।',6*k*k,rf'PQ={3*k} সেমি আঁক। P কেন্দ্র {5*k} ও Q কেন্দ্র {4*k} সেমি ব্যাসার্ধের চাপের ছেদ R; PR,QR যোগ কর। তিন বাহুর অনুপাত {k} হওয়ায় SSS-এ PQR∼ABC। 3,4,5 সমকোণী; মূল ক্ষেত্রফল 6, নতুনটি $6\times{k*k}={6*k*k}$ বর্গসেমি।'),pair(float(k)),k=k)
 add('inverse-area-scale',rf'দুটি সদৃশ ত্রিভুজের ক্ষেত্রফল 9 এবং {9*k*k} বর্গসেমি; ছোটটির একটি বাহু 5 সেমি।',Q('বড়/ছোট ক্ষেত্রফলের অনুপাত কত?',k*k,rf'${9*k*k}/9={k*k}$।'),Q('বড়টির অনুরূপ বাহু কত সেমি?',5*k,rf'রৈখিক গুণক $\sqrt{{{k*k}}}={k}$; বাহু ${5*k}$ সেমি।'),Q('বড়/ছোট পরিসীমার অনুপাত কত?',k,rf'প্রতিটি বাহুর অনুপাত {k}; পরিসীমার অনুপাতও {k}, ক্ষেত্রফলের অনুপাত নয়।'),pair(float(k)),k=k)
 add('median-scale',rf'দুটি সদৃশ ত্রিভুজের বড়/ছোট রৈখিক গুণক {k}। ছোটটির একটি মধ্যমা 6 ও অনুরূপ উচ্চতা 4 সেমি।',Q('বড়টির অনুরূপ উচ্চতা কত সেমি?',4*k,rf'সদৃশ ত্রিভুজের অনুরূপ লম্ব উচ্চতা একই গুণকে পরিবর্তিত; ${4*k}$।'),Q('বড়টির অনুরূপ মধ্যমা কত সেমি?',6*k,rf'অনুরূপ মধ্যবিন্দুতে যোগ করা রেখাংশের অনুপাতও {k}; মধ্যমা ${6*k}$ সেমি।'),Q('বড়/ছোট ক্ষেত্রফলের অনুপাত কত?',k*k,rf'ভূমি ও উচ্চতা উভয়ই {k} গুণ, ফলে ক্ষেত্রফল ${k*k}$ গুণ।'),pair(float(k)),k=k)
 add('circle-similarity',rf'দুটি বৃত্তের ব্যাসার্ধ 2 ও {2*k} সেমি।',Q('ব্যাসের বড়/ছোট অনুপাত কত?',k,rf'ব্যাস ব্যাসার্ধের দ্বিগুণ, তাই ${4*k}/4={k}$।'),Q('পরিধির বড়/ছোট অনুপাত কত?',k,rf'$2\pi({2*k})/(2\pi\cdot2)={k}$।'),Q('ক্ষেত্রফলের বড়/ছোট অনুপাত কত?',k*k,rf'$\pi({2*k})^2/(\pi\cdot2^2)={k*k}$; সব বৃত্ত সদৃশ।'),circles(2*k,2),k=k)
 add('origin-reflection',rf'A=({k},−3) বিন্দুর মূলবিন্দুর সাপেক্ষে প্রতিসম বিন্দু P।',Q('P-এর x-স্থানাঙ্ক কত?',-k,rf'কেন্দ্রীয় প্রতিসাম্য $(x,y)\mapsto(-x,-y)$; x={-k}।'),Q('P-এর y-স্থানাঙ্ক কত?',3,'−(−3)=3; এটি শুধু y-অক্ষে প্রতিফলন নয়।'),Q('AP² কত বর্গএকক?',4*(k*k+9),rf'$AP^2=({2*k})^2+(-6)^2={4*(k*k+9)}$; O হলো AP-এর মধ্যবিন্দু।'),plane(dict(A=(k,-3),P=(-k,3),O=(0,0)),['AP']),k=k)
 add('midpoint-similarity',rf'ত্রিভুজ ABC-তে D,E যথাক্রমে AB,AC-এর মধ্যবিন্দু; BC={2*k} সেমি এবং ABC-এর ক্ষেত্রফল {4*k*k} বর্গসেমি।',Q('AD/AB কত?',R(1,2),'মধ্যবিন্দুর সংজ্ঞায় AD=DB, তাই AD/AB=1/2।'),Q('DE কত সেমি?',k,rf'মধ্যবিন্দু উপপাদ্যে DE∥BC এবং $DE=BC/2={k}$।'),Q('BCED চতুর্ভুজের ক্ষেত্রফল কত বর্গসেমি?',3*k*k,rf'ADE∼ABC, ক্ষেত্রফলের অনুপাত 1:4; ADE-এর ক্ষেত্রফল {k*k}। অবশিষ্ট ${4*k*k}-{k*k}={3*k*k}$।'),midpoint(2*k,4*k),k=k)
 return rows

def scenarios15(n):
 k=S.Integer(n+2);rows=[]
 def add(*args,**kw):rows.append(row(*args,**kw))
 add('same-base-parallels',rf'AB={4*k} সেমি। C ও D, AB-এর একই পাশের AB-সমান্তরাল রেখায়; রেখাদ্বয়ের লম্ব দূরত্ব {3*k} সেমি। C,D ভিন্ন বিন্দু।',Q('C ও D থেকে AB-এর উপর লম্ব উচ্চতার পার্থক্য কত?',0,'দুটি সমান্তরাল রেখার মধ্যে লম্ব দূরত্ব সর্বত্র সমান; পার্থক্য 0।'),Q('ABC-এর ক্ষেত্রফল কত বর্গসেমি?',6*k*k,rf'$[ABC]=\frac12 AB\cdot h=\frac12({4*k})({3*k})={6*k*k}$।'),Q('ABC ও ABD-এর ক্ষেত্রফলের অনুপাতের ভগ্নাংশমান কত? প্রমাণ দাও।',1,r'একই ভূমি AB এবং একই সমান্তরালদ্বয়ের মধ্যে অবস্থিত হওয়ায় উচ্চতা h সমান। উভয় ক্ষেত্রফল $(1/2)AB\cdot h$; তাই সমান এবং অনুপাত 1।'),plane(dict(A=(0,0),B=(4*k,0),C=(k,3*k),D=(3*k,3*k)),['AB','BC','CA','AD','BD','CD']),k=k)
 add('parallelogram-diagonal',rf'সামান্তরিক ABCD-এর ভূমি AB={4*k} এবং লম্ব উচ্চতা {3*k} সেমি। কর্ণ AC আঁকা হয়েছে।',Q('সামান্তরিকের ক্ষেত্রফল কত বর্গসেমি?',12*k*k,rf'$AB\cdot h={4*k}\times{3*k}={12*k*k}$।'),Q('ABC-এর ক্ষেত্রফল কত বর্গসেমি?',6*k*k,rf'কর্ণ AC সামান্তরিককে সমান ক্ষেত্রফলের দুই ত্রিভুজে ভাগ করে; $[ABC]={12*k*k}/2={6*k*k}$।'),Q('ADC-এর ক্ষেত্রফল কত? সর্বসমতা দিয়ে সমতা প্রমাণ কর।',6*k*k,rf'AB=CD, BC=AD (সামান্তরিকের বিপরীত বাহু), AC সাধারণ। SSS-এ ABC ও CDA সর্বসম, তাই ক্ষেত্রফল সমান। $[ADC]={6*k*k}$ বর্গসেমি।'),para(4*k,3*k),k=k)
 add('median-halves',rf'ত্রিভুজ ABC-তে M হলো BC-এর মধ্যবিন্দু। BC={4*k}, A থেকে BC-এর উপর লম্ব উচ্চতা {3*k} সেমি।',Q('BM কত সেমি?',2*k,rf'$BM=BC/2={2*k}$।'),Q('ABM-এর ক্ষেত্রফল কত বর্গসেমি?',3*k*k,rf'$[ABM]=\frac12 BM\cdot h=\frac12({2*k})({3*k})={3*k*k}$।'),Q('AMC-এর ক্ষেত্রফল কত? মধ্যমার উপপাদ্যের যুক্তি দাও।',3*k*k,rf'BM=MC এবং A থেকে দুই সমরেখ ভূমিতে একই লম্ব উচ্চতা h। তাই $[ABM]/[AMC]=BM/MC=1$; $[AMC]={3*k*k}$।'),median(4*k,3*k),k=k)
 add('base-ratio',rf'ত্রিভুজ ABC-তে D∈BC, BD={2*k}, DC={3*k} সেমি। A থেকে BC-এর উপর লম্ব উচ্চতা {4*k} সেমি।',Q('BC কত সেমি?',5*k,rf'$BC=BD+DC={5*k}$।'),Q('ABD-এর ক্ষেত্রফল কত বর্গসেমি?',4*k*k,rf'$[ABD]=\frac12({2*k})({4*k})={4*k*k}$।'),Q('ADC-এর ক্ষেত্রফল কত? ক্ষেত্রফলের অনুপাত ভূমির অনুপাত কেন?',6*k*k,rf'উভয়ের উচ্চতা h সমান, তাই $[ABD]/[ADC]=BD/DC=2/3$। $[ADC]=\frac12({3*k})({4*k})={6*k*k}$ বর্গসেমি।'),plane(dict(A=(k,4*k),B=(0,0),C=(5*k,0),D=(2*k,0)),['AB','BC','CA','AD']),k=k)
 add('equal-area-converse',rf'ABC ও ABD ত্রিভুজ একই ভূমি AB={4*k} সেমির একই পাশে এবং প্রত্যেকটির ক্ষেত্রফল {6*k*k} বর্গসেমি।',Q('C থেকে AB-এর উপর লম্ব উচ্চতা কত সেমি?',3*k,rf'$h_C=2[ABC]/AB=2({6*k*k})/{4*k}={3*k}$।'),Q('D থেকে AB-এর উপর লম্ব উচ্চতা কত সেমি?',3*k,rf'একই সূত্রে $h_D=2({6*k*k})/{4*k}={3*k}$।'),Q('C ও D ভিন্ন হলে CD ও AB-এর মধ্যবর্তী লম্ব দূরত্ব কত সেমি? CD∥AB প্রমাণ কর।',3*k,rf'C,D একই পাশে একই লম্ব দূরত্ব {3*k}-এ। একটি সরলরেখার একই পাশের নির্দিষ্ট লম্ব দূরত্বে বিন্দুগুলোর সঞ্চারপথ তার সমান্তরাল সরলরেখা; তাই CD∥AB এবং দূরত্ব {3*k} সেমি। বিপরীত পাশে হলে এই সিদ্ধান্ত সরাসরি চলত না।'),plane(dict(A=(0,0),B=(4*k,0),C=(k,3*k),D=(3*k,3*k)),['AB','BC','CA','AD','BD','CD']),k=k)
 add('quadrilateral-to-triangle',rf'উত্তল চতুর্ভুজ ABCD-এর সহায়ক স্থানাঙ্ক A=(0,0), B=({4*k},0), C=({4*k},{2*k}), D=({k},{3*k}) সেমি। D দিয়ে AC-সমান্তরাল রেখা BC-এর C-পাশের বর্ধিতাংশকে E-তে ছেদ করে।',Q('ABC-এর ক্ষেত্রফল কত বর্গসেমি?',4*k*k,rf'$[ABC]=\frac12({4*k})({2*k})={4*k*k}$।'),Q('ABCD-এর ক্ষেত্রফল কত বর্গসেমি?',9*k*k,rf'$[ACD]=\frac12|({4*k})({3*k})-({2*k})({k})|={5*k*k}$। যোগে ${4*k*k}+{5*k*k}={9*k*k}$।'),Q('সমক্ষেত্র ত্রিভুজ ABE-এর ক্ষেত্রফল কত? নির্মাণের বিশুদ্ধ জ্যামিতিক যুক্তি দাও।',9*k*k,rf'AC যোগ করে D দিয়ে AC-এর সমান্তরাল এঁকে বর্ধিত BC-তে E নির্ণয় কর; AE যোগ কর। ACD ও ACE একই ভূমি AC ও একই সমান্তরাল AC,DE-এর মধ্যে, তাই সমক্ষেত্র। উভয়ের সঙ্গে ABC যোগে $[ABCD]=[ABE]={9*k*k}$। C, B ও E-এর মাঝে হওয়ায় যোগ গ্রহণযোগ্য।'),plane(dict(A=(0,0),B=(4*k,0),C=(4*k,2*k),D=(k,3*k),E=(4*k,R(9,2)*k)),['AB','BC','CD','DA','AC','DE','AE','CE']),k=k)
 add('rectangle-to-triangle',rf'আয়তক্ষেত্র ABCD-তে AB={3*k}, AD={2*k} সেমি। AB-কে B-এর দিকে বাড়িয়ে BE=AB নেওয়া হলো; DE যোগ করা হলো।',Q('AE কত সেমি?',6*k,rf'$AE=AB+BE=2AB={6*k}$।'),Q('ADE-এর ক্ষেত্রফল কত বর্গসেমি?',6*k*k,rf'$[ADE]=\frac12 AE\cdot AD=\frac12({6*k})({2*k})={6*k*k}$।'),Q('ADE এবং ABCD-এর ক্ষেত্রফলের অনুপাতের ভগ্নাংশমান কত? নির্মাণ কেন কাজ করে?',1,r'আয়তক্ষেত্রের ক্ষেত্রফল AB·AD। নির্মিত ত্রিভুজের ভূমি 2AB ও উচ্চতা AD, তাই ক্ষেত্রফলও AB·AD; অনুপাত 1। BE=AB কম্পাসে সমান দৈর্ঘ্য কেটে নেওয়া যায়।'),plane(dict(A=(0,0),B=(3*k,0),C=(3*k,2*k),D=(0,2*k),E=(6*k,0)),['AB','BC','CD','DA','BE','DE']),k=k)
 add('triangle-to-parallelogram',rf'ত্রিভুজ ABC-এর ভূমি BC={4*k} ও লম্ব উচ্চতা {3*k} সেমি। BC-এর মধ্যবিন্দু M; A দিয়ে BC-সমান্তরাল, M দিয়ে BA-সমান্তরাল রেখার ছেদ D নেওয়া হলো।',Q('BM কত সেমি?',2*k,rf'$BM=BC/2={2*k}$।'),Q('BMDA সামান্তরিকের ক্ষেত্রফল কত বর্গসেমি?',6*k*k,rf'BM∥AD, BA∥MD; ক্ষেত্রফল $BM\cdot h={2*k}\times{3*k}={6*k*k}$।'),Q('BMDA-এর ক্ষেত্রফল ABC-এর কত গুণ? নির্মাণের যুক্তি দাও।',1,r'$[BMDA]=BM\cdot h=(BC/2)h=[ABC]$। দুজোড়া বিপরীত বাহু সমান্তরাল হওয়ায় নির্মিত চতুর্ভুজ সামান্তরিক; অর্থাৎ সমক্ষেত্র রূপান্তর, সদৃশতা দাবি নয়।'),plane(dict(A=(k,3*k),B=(0,0),C=(4*k,0),M=(2*k,0),D=(3*k,3*k)),['AB','BC','CA','MD','AD']),k=k)
 add('equal-parallelograms',rf'ABCD ও ABEF একই ভূমি AB={4*k} সেমি ও একই সমান্তরাল AB,DF-এর মধ্যে দুটি সামান্তরিক। লম্ব উচ্চতা {2*k} সেমি।',Q('ABCD-এর ক্ষেত্রফল কত বর্গসেমি?',8*k*k,rf'$AB\cdot h={4*k}\times{2*k}={8*k*k}$।'),Q('ABEF-এর ক্ষেত্রফল কত বর্গসেমি?',8*k*k,rf'একই ভূমি ও একই সমান্তরালের মধ্যে উচ্চতা সমান; তাই $[ABEF]={8*k*k}$।'),Q('ক্ষেত্রফলের পার্থক্য কত? সমান পরিসীমা হওয়া কি বাধ্যতামূলক?',0,'পার্থক্য 0। ক্ষেত্রফলে শুধু ভূমি ও লম্ব উচ্চতা কাজ করে; তির্যক বাহুর দৈর্ঘ্য আলাদা হতে পারে। অতএব ক্ষেত্রফল সমান হলেও পরিসীমা সমান হওয়া বাধ্যতামূলক নয়।'),plane(dict(A=(0,0),B=(4*k,0),C=(5*k,2*k),D=(k,2*k),E=(6*k,2*k),F=(2*k,2*k)),['AB','BC','CD','DA','BE','EF','FA','DF']),k=k)
 add('equal-area-rectangle',rf'একটি ত্রিভুজের ভূমি {6*k} ও লম্ব উচ্চতা {4*k} সেমি। সমক্ষেত্র আয়তক্ষেত্রের একটি বাহু {3*k} সেমি নির্দিষ্ট।',Q('ত্রিভুজের ক্ষেত্রফল কত বর্গসেমি?',12*k*k,rf'$\frac12({6*k})({4*k})={12*k*k}$।'),Q('আয়তক্ষেত্রের অপর বাহু কত সেমি?',4*k,rf'ক্ষেত্রফল/নির্দিষ্ট বাহু $={12*k*k}/{3*k}={4*k}$ সেমি।'),Q('সমক্ষেত্র আয়তক্ষেত্রের পরিসীমা কত সেমি? নির্মাণ লেখ।',14*k,rf'AB={3*k} সেমি আঁক; A,B-তে AB-এর একই পাশে লম্ব তুলে AD=BC={4*k} সেমি কাট; C,D যোগ কর। আয়তক্ষেত্রের ক্ষেত্রফল ${12*k*k}$, ত্রিভুজের সমান; পরিসীমা $2({3*k}+{4*k})={14*k}$ সেমি।'),rect(3*k,4*k),k=k)
 add('trapezium-diagonal',rf'ট্রাপিজিয়াম ABCD-তে AB∥DC, AB={4*k}, DC={2*k} ও উচ্চতা {3*k} সেমি। কর্ণ AC অঙ্কিত।',Q('ABC-এর ক্ষেত্রফল কত বর্গসেমি?',6*k*k,rf'$[ABC]=\frac12 AB\cdot h={6*k*k}$।'),Q('ADC-এর ক্ষেত্রফল কত বর্গসেমি?',3*k*k,rf'$[ADC]=\frac12 DC\cdot h={3*k*k}$।'),Q('ABCD-এর ক্ষেত্রফল কত? ত্রিভুজ যোগ করে সূত্র প্রতিষ্ঠা কর।',9*k*k,rf'$[ABCD]=[ABC]+[ADC]=\frac12(AB+DC)h={9*k*k}$ বর্গসেমি।'),plane(dict(A=(0,0),B=(4*k,0),C=(3*k,3*k),D=(k,3*k)),['AB','BC','CD','DA','AC']),k=k)
 add('midpoint-area',rf'ত্রিভুজ ABC-তে D,E যথাক্রমে AB ও AC-এর মধ্যবিন্দু। BC={4*k} ও লম্ব উচ্চতা {4*k} সেমি।',Q('ABC-এর ক্ষেত্রফল কত বর্গসেমি?',8*k*k,rf'$\frac12({4*k})({4*k})={8*k*k}$।'),Q('ADE-এর ক্ষেত্রফল কত বর্গসেমি?',2*k*k,rf'DE∥BC, DE=BC/2 এবং ADE-এর উচ্চতাও মূল উচ্চতার অর্ধেক। তাই ক্ষেত্রফল মূলের 1/4, অর্থাৎ {2*k*k}।'),Q('BCED-এর ক্ষেত্রফল কত বর্গসেমি?',6*k*k,rf'বিয়োগে ${8*k*k}-{2*k*k}={6*k*k}$। শুধু ভূমি অর্ধেক বলে ক্ষেত্রফল অর্ধেক নয়; উচ্চতাও অর্ধেক।'),midpoint(4*k,4*k),k=k)
 add('median-point-ratio',rf'ABC-তে M হলো BC-এর মধ্যবিন্দু এবং G∈AM; AG:GM=2:1। ABC-এর ভূমি {6*k} ও উচ্চতা {4*k} সেমি।',Q('ABC-এর ক্ষেত্রফল কত বর্গসেমি?',12*k*k,rf'$\frac12({6*k})({4*k})={12*k*k}$।'),Q('GBC-এর ক্ষেত্রফল কত বর্গসেমি?',4*k*k,rf'G থেকে BC-এর লম্ব দূরত্ব A-এর উচ্চতার 1/3: একই সরলরেখা AM-এ GM/AM=1/3। একই ভূমি BC-এ $[GBC]=[ABC]/3={4*k*k}$।'),Q('G-এর কারণে উপরের ABG ও ACG ত্রিভুজের মোট ক্ষেত্রফল কত বর্গসেমি?',8*k*k,rf'বিয়োগে $[ABG]+[ACG]=[ABC]-[GBC]={12*k*k}-{4*k*k}={8*k*k}$।'),plane(dict(A=(2*k,4*k),B=(0,0),C=(6*k,0),M=(3*k,0),G=(R(8,3)*k,R(4,3)*k)),['AB','BC','CA','AM','BG','CG']),k=k)
 add('diagonal-four-triangles',rf'সামান্তরিক ABCD-এর কর্ণদ্বয় O-তে ছেদ করে। ভূমি {4*k} ও উচ্চতা {4*k} সেমি।',Q('সামান্তরিকের ক্ষেত্রফল কত বর্গসেমি?',16*k*k,rf'$bh={4*k}\times{4*k}={16*k*k}$।'),Q('AOB-এর ক্ষেত্রফল কত বর্গসেমি?',4*k*k,rf'সামান্তরিকের কর্ণদ্বয় পরস্পরকে সমদ্বিখণ্ডিত করে। ABC-তে BO মধ্যমা, তাই AOB ও BOC সমক্ষেত্র; প্রত্যেকটি সামান্তরিকের 1/4, অর্থাৎ {4*k*k}।'),Q('AOB ও COD-এর মোট ক্ষেত্রফল কত বর্গসেমি?',8*k*k,rf'চার ত্রিভুজই সমক্ষেত্র; বিপরীত দুটির মোট $2({4*k*k})={8*k*k}$।'),para(4*k,4*k),k=k)
 add('double-triangle',rf'ABC-এর ভূমি BC={3*k}, উচ্চতা {2*k} সেমি। BC-কে C-এর দিকে বাড়িয়ে CD=BC কাটা হলো; AD যোগ করা হলো।',Q('BD কত সেমি?',6*k,rf'$BD=BC+CD={6*k}$।'),Q('ABD-এর ক্ষেত্রফল কত বর্গসেমি?',6*k*k,rf'একই A থেকে একই সরলরেখায় উচ্চতা {2*k}; $[ABD]=\frac12({6*k})({2*k})={6*k*k}$।'),Q('ABD ও ABC-এর ক্ষেত্রফলের অনুপাতের ভগ্নাংশমান কত?',2,'একই উচ্চতায় ক্ষেত্রফলের অনুপাত ভূমির অনুপাত BD/BC=2। CD=BC কম্পাসে কেটে নির্মাণ করলেই দ্বিগুণ ক্ষেত্রের ত্রিভুজ পাওয়া যায়।'),plane(dict(A=(k,2*k),B=(0,0),C=(3*k,0),D=(6*k,0)),['AB','BC','CA','CD','AD']),k=k)
 return rows

def scenarios16(n):
 k=S.Integer(n+2);pi=S.pi;rows=[]
 def add(*args,**kw):rows.append(row(*args,**kw))
 add('cube',rf'একটি ঘনকের বাহু {k} সেমি।',Q('একটি তলের ক্ষেত্রফল কত বর্গসেমি?',k*k,rf'$a^2={k}^2={k*k}$।'),Q('ঘনকের আয়তন কত ঘনসেমি?',k**3,rf'$V=a^3={k**3}$।'),Q('সমগ্র পৃষ্ঠের ক্ষেত্রফল কত বর্গসেমি এবং কর্ণ কত সেমি?',6*k*k,rf'$A=6a^2={6*k*k}$ বর্গসেমি। তলকর্ণ $a\sqrt2$ এবং দেহকর্ণ $\sqrt{{(a\sqrt2)^2+a^2}}={T(k*S.sqrt(3))}$ সেমি।'),solid('cube',k,k,k),k=k)
 add('cuboid',rf'একটি আয়তাকার ঘনবস্তুর দৈর্ঘ্য {3*k}, প্রস্থ {2*k}, উচ্চতা {k} সেমি।',Q('ভূমির ক্ষেত্রফল কত বর্গসেমি?',6*k*k,rf'$lw={3*k}\times{2*k}={6*k*k}$।'),Q('আয়তন কত ঘনসেমি?',6*k**3,rf'$V=lwh={6*k**3}$।'),Q('সমগ্র পৃষ্ঠের ক্ষেত্রফল কত বর্গসেমি?',22*k*k,rf'$A=2(lw+wh+hl)=2({6*k*k}+{2*k*k}+{3*k*k})={22*k*k}$।'),solid('cuboid',2*k,k,3*k),k=k)
 add('cylinder',rf'একটি সমবৃত্তভূমিক লম্ব বেলনের ব্যাসার্ধ {k} এবং উচ্চতা {3*k} সেমি। π-এর মান প্রতীকেই রাখ।',Q('ভূমির ক্ষেত্রফল কত বর্গসেমি?',pi*k*k,rf'$\pi r^2={T(pi*k*k)}$।'),Q('বেলনের আয়তন কত ঘনসেমি?',3*pi*k**3,rf'$V=\pi r^2h={T(3*pi*k**3)}$।'),Q('সমগ্র পৃষ্ঠের ক্ষেত্রফল কত বর্গসেমি? দুই ভূমি অন্তর্ভুক্ত কর।',8*pi*k*k,rf'বক্রতল $2\pi rh={T(6*pi*k*k)}$; দুই ভূমি $2\pi r^2={T(2*pi*k*k)}$। যোগে ${T(8*pi*k*k)}$।'),solid('cylinder',k,3*k),k=k)
 add('cone',rf'একটি সমবৃত্তভূমিক লম্ব শঙ্কুর ব্যাসার্ধ {3*k}, উচ্চতা {4*k} সেমি। π প্রতীকেই রাখ।',Q('তির্যক উচ্চতা কত সেমি?',5*k,rf'$s=\sqrt{{r^2+h^2}}=\sqrt{{({3*k})^2+({4*k})^2}}={5*k}$।'),Q('শঙ্কুর আয়তন কত ঘনসেমি?',12*pi*k**3,rf'$V=\frac13\pi r^2h={T(12*pi*k**3)}$।'),Q('সমগ্র পৃষ্ঠের ক্ষেত্রফল কত বর্গসেমি?',24*pi*k*k,rf'$A=\pi rs+\pi r^2={T(15*pi*k*k)}+{T(9*pi*k*k)}={T(24*pi*k*k)}$। তির্যক উচ্চতার জায়গায় লম্ব উচ্চতা বসানো যাবে না।'),solid('cone',3*k,4*k,5*k),k=k)
 add('sphere',rf'একটি গোলকের ব্যাসার্ধ {k} সেমি। π প্রতীকেই রাখ।',Q('ব্যাস কত সেমি?',2*k,rf'$d=2r={2*k}$।'),Q('গোলকের আয়তন কত ঘনসেমি?',R(4,3)*pi*k**3,rf'$V=\frac43\pi r^3={T(R(4,3)*pi*k**3)}$।'),Q('সমগ্র পৃষ্ঠের ক্ষেত্রফল কত বর্গসেমি এবং দ্বিগুণ ব্যাসার্ধে এটি কত গুণ হবে?',4*pi*k*k,rf'$A=4\pi r^2={T(4*pi*k*k)}$। দ্বিগুণ ব্যাসার্ধে ক্ষেত্রফল $2^2=4$ গুণ; আয়তন $2^3=8$ গুণ।'),solid('sphere',k),k=k)
 add('hemisphere',rf'একটি নিরেট অর্ধগোলকের ব্যাসার্ধ {k} সেমি। সমতল বৃত্তাকার তলসহ হিসাব কর; π প্রতীকেই রাখ।',Q('বক্রতলের ক্ষেত্রফল কত বর্গসেমি?',2*pi*k*k,rf'গোলকের পৃষ্ঠের অর্ধেক $2\pi r^2={T(2*pi*k*k)}$।'),Q('অর্ধগোলকের আয়তন কত ঘনসেমি?',R(2,3)*pi*k**3,rf'$V=\frac12\cdot\frac43\pi r^3={T(R(2,3)*pi*k**3)}$।'),Q('সমগ্র পৃষ্ঠের ক্ষেত্রফল কত বর্গসেমি?',3*pi*k*k,rf'বক্রতল ও ভূমির যোগ $2\pi r^2+\pi r^2=3\pi r^2={T(3*pi*k*k)}$।'),solid('hemisphere',k),k=k)
 add('equilateral',rf'একটি সমবাহু ত্রিভুজের বাহু {2*k} সেমি।',Q('পরিসীমা কত সেমি?',6*k,rf'$3a=3({2*k})={6*k}$।'),Q('ক্ষেত্রফল কত বর্গসেমি?',S.sqrt(3)*k*k,rf'$A=\frac{{\sqrt3}}4a^2={T(S.sqrt(3)*k*k)}$।'),Q('লম্ব উচ্চতা কত সেমি? পিথাগোরাস প্রয়োগ কর।',S.sqrt(3)*k,rf'শীর্ষ থেকে ভূমিতে লম্ব ভূমিকে সমদ্বিখণ্ডিত করে। $h=\sqrt{{({2*k})^2-{k}^2}}={T(S.sqrt(3)*k)}$ সেমি।'),plane(dict(A=(k,float(S.sqrt(3)*k)),B=(0,0),C=(2*k,0),M=(k,0)),['AB','BC','CA','AM'],right=['AMB']),k=k)
 add('heron',rf'একটি ত্রিভুজের তিন বাহু {13*k}, {14*k}, {15*k} সেমি।',Q('অর্ধপরিসীমা s কত সেমি?',21*k,rf'$s=({13*k}+{14*k}+{15*k})/2={21*k}$।'),Q('হেরনের সূত্রে ক্ষেত্রফল কত বর্গসেমি?',84*k*k,rf'$A=\sqrt{{s(s-a)(s-b)(s-c)}}=\sqrt{{({21*k})({8*k})({7*k})({6*k})}}={84*k*k}$।'),Q(rf'{14*k} সেমি বাহুর উপর লম্ব উচ্চতা কত সেমি?',12*k,rf'$h=2A/b=2({84*k*k})/{14*k}={12*k}$ সেমি।'),plane(dict(A=(5*k,12*k),B=(0,0),C=(14*k,0),M=(5*k,0)),['AB','BC','CA','AM'],right=['AMB']),k=k)
 add('annulus',rf'দুটি সমকেন্দ্রিক বৃত্তের বাইরের ব্যাসার্ধ {3*k}, ভিতরের ব্যাসার্ধ {k} সেমি। π প্রতীকেই রাখ।',Q('বলয়ের সমান প্রস্থ কত সেমি?',2*k,rf'$R-r={3*k}-{k}={2*k}$।'),Q('বলয়ের ক্ষেত্রফল কত বর্গসেমি?',8*pi*k*k,rf'$A=\pi(R^2-r^2)=\pi[({3*k})^2-{k}^2]={T(8*pi*k*k)}$।'),Q('বলয়ের দুই সীমানার মোট দৈর্ঘ্য কত সেমি?',8*pi*k,rf'বাইরের ও ভিতরের উভয় পরিধি $2\pi R+2\pi r=2\pi({3*k}+{k})={T(8*pi*k)}$।'),circles(3*k,k),k=k)
 add('composite-solid',rf'একটি বেলনের ব্যাসার্ধ {k} ও উচ্চতা {2*k} সেমি। একই ব্যাসার্ধের একটি অর্ধগোলক তার উপরে তল-তলে যুক্ত; নিচের বৃত্তাকার তলও বাইরের পৃষ্ঠের অংশ হিসেবে গণ্য। π প্রতীকেই রাখ।',Q('নিরেট বস্তুর মোট উচ্চতা কত সেমি?',3*k,rf'বেলনের উচ্চতা+অর্ধগোলকের ব্যাসার্ধ $={2*k}+{k}={3*k}$।'),Q('নিরেট বস্তুর আয়তন কত ঘনসেমি?',R(8,3)*pi*k**3,rf'$V=\pi r^2({2*k})+\frac23\pi r^3={T(R(8,3)*pi*k**3)}$।'),Q('বাইরে দৃশ্যমান সমগ্র পৃষ্ঠের ক্ষেত্রফল কত বর্গসেমি?',7*pi*k*k,rf'বেলনের বক্রতল $4\pi r^2$, অর্ধগোলকের বক্রতল $2\pi r^2$ এবং নিচের তল $\pi r^2$। যোগ $7\pi r^2={T(7*pi*k*k)}$। সংযুক্ত অভ্যন্তরীণ বৃত্তদ্বয় বাইরে দৃশ্যমান নয়, তাই যোগ হবে না।'),solid('cylinder-hemisphere',k,2*k),k=k)
 add('rectangle-path',rf'{6*k} মিটার দৈর্ঘ্য ও {4*k} মিটার প্রস্থের আয়তাকার বাগানের ভিতর চারদিকে {k} মিটার চওড়া পথ।',Q('পথ বাদে ভিতরের দৈর্ঘ্য কত মিটার?',4*k,rf'$L-2w={6*k}-{2*k}={4*k}$।'),Q('পথের ক্ষেত্রফল কত বর্গমিটার?',16*k*k,rf'বাইরের ক্ষেত্রফল {24*k*k}, ভিতরের মাপ {4*k}×{2*k}, ক্ষেত্রফল {8*k*k}। পার্থক্য {16*k*k}। কোণের অংশ আলাদা যোগ করলে দ্বিগুণ গণনা হতো।'),Q('পথ বাদে ভিতরের পরিসীমা কত মিটার?',12*k,rf'$2({4*k}+{2*k})={12*k}$ মিটার।'),plane(dict(A=(0,0),B=(6*k,0),C=(6*k,4*k),D=(0,4*k),P=(k,k),Q=(5*k,k),R=(5*k,3*k),S=(k,3*k)),['AB','BC','CD','DA','PQ','QR','RS','SP']),k=k)
 add('square-diagonal',rf'একটি বর্গের কর্ণ ${T(k*S.sqrt(2))}$ মিটার।',Q('বাহুর দৈর্ঘ্য কত মিটার?',k,rf'$a=d/\sqrt2={k}$ মিটার।'),Q('ক্ষেত্রফল কত বর্গমিটার?',k*k,rf'$A=d^2/2=[({T(k*S.sqrt(2))})^2]/2={k*k}$।'),Q('পরিসীমা কত মিটার?',4*k,rf'$P=4a={4*k}$ মিটার।'),rect(k,k),k=k)
 add('trapezium',rf'একটি ট্রাপিজিয়ামের সমান্তরাল বাহুদ্বয় {5*k} ও {3*k} সেমি; লম্ব উচ্চতা {2*k} সেমি।',Q('সমান্তরাল বাহুদ্বয়ের যোগ কত সেমি?',8*k,rf'${5*k}+{3*k}={8*k}$।'),Q('ক্ষেত্রফল কত বর্গসেমি?',8*k*k,rf'$A=\frac12(a+b)h=\frac12({8*k})({2*k})={8*k*k}$।'),Q('সমান্তরাল বাহুদ্বয়ের মধ্যবর্তী মধ্যরেখার দৈর্ঘ্য কত সেমি?',4*k,rf'মধ্যরেখা $m=(a+b)/2={4*k}$; তাই ক্ষেত্রফল $mh={8*k*k}$।'),plane(dict(A=(0,0),B=(5*k,0),C=(4*k,2*k),D=(k,2*k)),['AB','BC','CD','DA']),k=k)
